queries.sql:
SELECT SUM(length_km) AS total_motorway_length_km
FROM roads
WHERE class = 'motorway';

SELECT SUM(length_km) AS total_trunk_length_km
FROM roads
WHERE class = 'trunk';

SELECT COUNT(DISTINCT name) AS count_distinct_named_motorway_segments
FROM roads
WHERE class = 'motorway' AND is_named = TRUE AND name IS NOT NULL;
